routes.accessibility=['va-hisa','va-sah','va-sha','va-tra','az-daas','az-cil-ability360','az-cil-assist','az-cil-direct','az-cil-nhdec','az-cil-smile','va-location-finder',...DATA.filter(x=>x.regional_role==='aging_agency').map(x=>x.program_id)];
